// Generated by AI
using UnityEngine;

public class PlayerController : MonoBehaviour
{

    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpForce = 8f;

    [Header("Audio Settings")]
    [SerializeField] private AudioClip movementClip;
    [SerializeField] private AudioClip jumpClip;
    [SerializeField] private AudioClip crouchClip;
    [SerializeField] private AudioClip pickupClip;

    private AudioSource audioSource;
    private Rigidbody2D rb;

    private float moveInput;

    //Tracks whether movement is being controlled through the HUD.
    private bool usingHUD = false;
    private void Start()
    {
        rb = GetComponent<Rigidbody2D>();
        audioSource = GetComponent<AudioSource>();
    }
    private void Update()
    {
        if (!PauseMenuController.GameStarted)
            return;

        // Read keyboard input only when HUD controls are inactive.
        if (!usingHUD)
        {
            moveInput = 0f;

            if (Input.GetKey(KeyCode.RightArrow))
            {
                moveInput = 1f;
            }

            if (Input.GetKey(KeyCode.LeftArrow))
            {
                moveInput = -1f;
            }
            if (Input.GetKeyDown(KeyCode.UpArrow))
            {
                Jump();
            }
        }
    }

    private void FixedUpdate()
    {
        // Apply horizontal movement while preserving vertical velocity.
        rb.linearVelocity = new Vector2(
            moveInput * moveSpeed,
            rb.linearVelocity.y
        );
    }

    public void SetMoveSpeed(float speed)
    {
        moveSpeed = speed;
    }

    // HUD movement controls.
    public void MoveRight()
    {
        usingHUD = true;
        moveInput = 1f;

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(movementClip);
        }
    }

    public void MoveLeft()
    {
        usingHUD = true;
        moveInput = -1f;

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(movementClip);
        }
    }

    public void StopMovement()
    {
        usingHUD = false;
        moveInput = 0f;
    }

    // Applies the jump force while preserving horizontal velocity.
    public void Jump()
    {
        rb.linearVelocity =
            new Vector2(
            rb.linearVelocity.x,
            jumpForce);

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(jumpClip);
        }

    }

    // HUD crouch action.
    public void Crouch()
    {
        Debug.Log("Crouch");

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(crouchClip);
        }
    }

    // HUD pickup action.
    public void Pickup()
    {
        Debug.Log("Pickup");

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(pickupClip);
        }
    }


}
